import{_ as t,o as a,c as i,ah as r}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Research: The Advertisement Affair (Media Corruption)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/inseraten-affaere.md","filePath":"en/recherche/inseraten-affaere.md"}'),o={name:"en/recherche/inseraten-affaere.md"};function n(s,e,h,c,l,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="research-the-advertisement-affair-media-corruption" tabindex="-1">Research: The Advertisement Affair (Media Corruption) <a class="header-anchor" href="#research-the-advertisement-affair-media-corruption" aria-label="Permalink to &quot;Research: The Advertisement Affair (Media Corruption)&quot;">​</a></h1><p><strong>When Steuergeld (tax money) buys positive headlines – The &quot;Kurz System&quot; and its methods.</strong></p><p>The Advertisement Affair, which came to light through the Thomas Schmid chats, is a central theme in Part 4 of our mockumentary. It shows how media power and political influence were systematically manipulated through public funds.</p><hr><h2 id="the-beinschab-osterreich-tool" tabindex="-1">The &quot;Beinschab-Österreich-Tool&quot; <a class="header-anchor" href="#the-beinschab-osterreich-tool" aria-label="Permalink to &quot;The &quot;Beinschab-Österreich-Tool&quot;&quot;">​</a></h2><p>The WKStA (Economic and Corruption Prosecutor&#39;s Office) suspects that the Ministry of Finance, under the direction of Thomas Schmid, used tax money to commission manipulated polls from the pollster Sabine Beinschab. These polls were then published in the tabloid newspaper <em>Österreich</em> (Fellner group).</p><h3 id="the-mechanism" tabindex="-1">The Mechanism: <a class="header-anchor" href="#the-mechanism" aria-label="Permalink to &quot;The Mechanism:&quot;">​</a></h3><ol><li><strong>Manipulated Polls:</strong> Surveys were &quot;beautified&quot; to favor Sebastian Kurz.</li><li><strong>Advertisements as Payment:</strong> In return for publishing these polls and positive reporting, the Ministry of Finance placed expensive advertisements in the newspaper.</li><li><strong>Corruption Verdacht:</strong> This circuit of &quot;Polls - Ads - Headlines&quot; is investigated as embezzlement and bribery.</li></ol><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>The advertisement affair is the modern equivalent of the &quot;market consolidation&quot; of the 1930s. While Helmut Horten acquired physical department stores, the actors around Sebastian Kurz &quot;acquired&quot; media space and public opinion.</p><ul><li><strong>Satirical Motif:</strong> We use the &quot;Beinschab-Tool&quot; as a metaphor for the construction of reality. In our film, we show how headlines are painted like pointillist dots until they form a beautiful, but false, picture of a politician.</li></ul><hr><p><em>Sources: Investigation files of the WKStA, chat protocols of Thomas Schmid, reporting by the ORF and investigative media.</em></p>',14)])])}const f=t(o,[["render",n]]);export{m as __pageData,f as default};
